const {test}=require('node:test');const assert=require('node:assert/strict');const {execFileSync}=require('node:child_process');const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),c=require('node:crypto');
// Independent Node ECDH/HKDF/GCM receiver verifies bytes generated by the Java sender.
test('Java WebPush decrypts using independent Node implementation; VAPID signature verifies',()=>{
 const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'bridge-crypto-'));try{
 const project=path.resolve(__dirname,'..');const android=fs.existsSync(path.join(project,'android'))?path.join(project,'android'):path.join(project,'../SmsBridge');
 const compilerArgs=['-d',tmp,path.join(android,'app/src/main/java/dev/kats/smsbridge/WebPush.java'),path.join(android,'tests/WebPushCheck.java')];if(process.env.ECJ_JAR)execFileSync('java',['-jar',process.env.ECJ_JAR,'-17',...compilerArgs]);else execFileSync('javac',compilerArgs);
 const [priv,pub,secret,body,header]=execFileSync('java',['-cp',tmp,'dev.kats.smsbridge.WebPushCheck'],{encoding:'utf8'}).trim().split('\n');
 const ua=Buffer.from(pub,'base64url'),auth=Buffer.from(secret,'base64url'),wire=Buffer.from(body,'base64url');
 const sender=c.createPublicKey({key:{kty:'EC',crv:'P-256',x:wire.subarray(22,54).toString('base64url'),y:wire.subarray(54,86).toString('base64url')},format:'jwk'});
 const shared=c.diffieHellman({privateKey:c.createPrivateKey({key:Buffer.from(priv,'base64url'),format:'der',type:'pkcs8'}),publicKey:sender});
 const ikm=Buffer.from(c.hkdfSync('sha256',shared,auth,Buffer.concat([Buffer.from('WebPush: info\0'),ua,wire.subarray(21,86)]),32));
 const cek=Buffer.from(c.hkdfSync('sha256',ikm,wire.subarray(0,16),Buffer.from('Content-Encoding: aes128gcm\0'),16));
 const nonce=Buffer.from(c.hkdfSync('sha256',ikm,wire.subarray(0,16),Buffer.from('Content-Encoding: nonce\0'),12));
 const d=c.createDecipheriv('aes-128-gcm',cek,nonce);d.setAuthTag(wire.subarray(-16));const plain=Buffer.concat([d.update(wire.subarray(86,-16)),d.final()]);
 assert.equal(plain.subarray(0,-1).toString(),'Тест BANK 900 🔐');assert.equal(plain.at(-1),2);assert.equal(wire.readUInt32BE(16),4096);
 const match=/vapid t=(.*), k=(.*)/.exec(header),jwt=match[1].split('.'),vk=Buffer.from(match[2],'base64url');
 assert.equal(JSON.parse(Buffer.from(jwt[1],'base64url')).aud,'https://web.push.apple.com');
 assert.equal(c.verify('sha256',Buffer.from(jwt.slice(0,2).join('.')),{key:c.createPublicKey({key:{kty:'EC',crv:'P-256',x:vk.subarray(1,33).toString('base64url'),y:vk.subarray(33).toString('base64url')},format:'jwk'}),dsaEncoding:'ieee-p1363'},Buffer.from(jwt[2],'base64url')),true);
 }finally{fs.rmSync(tmp,{recursive:true,force:true});}
});
